"use strict";(Array.isArray(self.webpackChunkwoocommerce_multivendor_marketplace_docs)?self.webpackChunkwoocommerce_multivendor_marketplace_docs:self.webpackChunkwoocommerce_multivendor_marketplace_docs=[]).push([[4720],{37207(e,t,a){a.r(t),a.d(t,{comp:()=>c,data:()=>h});var n=a(20641);const r=a.p+"assets/img/marketplace-vendor-image-enhancer-overview.ce5fc4b0.webp",o=a.p+"assets/img/marketplace-vendor-product-image-enhancer-trigger.a88d637c.webp",i=a.p+"assets/img/marketplace-vendor-image-enhancer-modal-prompt.512cc042.webp",s=a.p+"assets/img/marketplace-vendor-image-enhancer-modal-result.f07dfbd1.webp",l=a.p+"assets/img/marketplace-vendor-image-enhancer-applied.5b1031e4.webp",d={},c=(0,a(66262).A)(d,[["render",function(e,t){return(0,n.uX)(),(0,n.CE)("div",null,t[0]||(t[0]=[(0,n.Fv)('<h1 id="product-image-enhancer-thumbnail-ai-tool" tabindex="-1"><a class="header-anchor" href="#product-image-enhancer-thumbnail-ai-tool"><span>Product Image Enhancer (Thumbnail AI Tool)</span></a></h1><p>The <strong>Product Image Enhancer</strong> is an artificial intelligence tool engineered specifically for product thumbnails. It transforms ordinary photos into studio-grade e-commerce imagery while preserving the physical authenticity of the product.</p><p><a class="doc-image-link" href="./assets/marketplace-vendor-image-enhancer-overview.webp"><img src="'+r+'" alt="Product Image Enhancer AI Studio Transformation Overview"></a></p><table><thead><tr><th>Raw Vendor Photo</th><th>AI-Enhanced Thumbnail</th></tr></thead><tbody><tr><td>• Dim or uneven home lighting<br>• Distracting messy background<br>• Flat mobile camera angles</td><td>• Balanced professional studio lighting<br>• Crisp, pure white or styled scene<br>• High-converting lifestyle presentation</td></tr></tbody></table><hr><h2 id="_1-accessing-the-image-enhancer" tabindex="-1"><a class="header-anchor" href="#_1-accessing-the-image-enhancer"><span>1. Accessing the Image Enhancer</span></a></h2><p>The Image Enhancer is located right where sellers manage their product visuals:</p><ol><li>Log in to your <strong>Seller Dashboard</strong>.</li><li>Navigate to <strong>Products</strong> and open any existing product in <strong>Edit</strong> mode, or click <strong>Add Product</strong> to start a new listing.</li><li>Upload or select your base product photo in the standard <strong>Product Image</strong> box.</li><li>Directly beneath the uploaded image preview, click the dedicated trigger button:<br><strong>[ Enhance image with AI ]</strong></li></ol><blockquote><p><strong>Location on Form:</strong><br> In the seller <strong>Product Image</strong> panel, directly below the main uploaded product thumbnail preview, vendors see the dedicated <strong>[ Enhance image with AI ]</strong> button.</p></blockquote><p><a class="doc-image-link" href="./assets/marketplace-vendor-product-image-enhancer-trigger.webp"><img src="'+o+'" alt="Enhance Image with AI Button on Seller Product Form"></a></p><div class="hint-container tip"><p class="hint-container-title">Image Upload Required</p><p>You must have a base image uploaded in the thumbnail box before launching the enhancer. If the box is empty, upload your raw product photo first.</p></div><hr><h2 id="_2-step-by-step-enhancement-workflow" tabindex="-1"><a class="header-anchor" href="#_2-step-by-step-enhancement-workflow"><span>2. Step-by-Step Enhancement Workflow</span></a></h2><p>Clicking <strong>Enhance image with AI</strong> opens the dedicated side-by-side comparison modal:</p><table><thead><tr><th>Left Column: Original Image</th><th>Right Column: AI Enhanced Preview</th></tr></thead><tbody><tr><td>Displays the vendor&#39;s untouched starting photo for live visual comparison.</td><td>Displays the AI-generated high-resolution enhanced variation based on your prompt.</td></tr></tbody></table><h3 id="step-1-side-by-side-visual-inspection" tabindex="-1"><a class="header-anchor" href="#step-1-side-by-side-visual-inspection"><span>Step 1: Side-by-Side Visual Inspection</span></a></h3><p>The modal opens with a clear dual-column layout:</p><ul><li><strong>Left Column (Original Image):</strong> Displays your untouched base photograph so you can always reference your starting point.</li><li><strong>Right Column (AI Enhanced Preview):</strong> Displays the enhanced output once generated.</li></ul><h3 id="step-2-formulate-your-enhancement-prompt" tabindex="-1"><a class="header-anchor" href="#step-2-formulate-your-enhancement-prompt"><span>Step 2: Formulate Your Enhancement Prompt</span></a></h3><p>In the prompt field at the bottom of the modal, describe the environment, lighting, or staging you want:</p><table><thead><tr><th>Desired Look</th><th>Recommended Prompt Formula</th><th>Example Prompt</th></tr></thead><tbody><tr><td><strong>Clean Studio</strong></td><td><em>&quot;Place item on a seamless pure white studio background with soft commercial lighting and subtle natural contact shadows.&quot;</em></td><td><em>&quot;Pure white background, clean product shot, soft diffuse lighting, studio quality.&quot;</em></td></tr><tr><td><strong>Modern Lifestyle</strong></td><td><em>&quot;Place item naturally on a [surface] in a [setting] with soft ambient daylight.&quot;</em></td><td><em>&quot;Place naturally on a rustic oak coffee table in a sunlit living room with subtle out-of-focus background greenery.&quot;</em></td></tr><tr><td><strong>Luxury / Premium</strong></td><td><em>&quot;Set on a [luxurious surface] with dramatic accent lighting and elegant reflections.&quot;</em></td><td><em>&quot;Set on a polished dark marble tabletop with warm side lighting and subtle depth of field.&quot;</em></td></tr></tbody></table><p><a class="doc-image-link" href="./assets/marketplace-vendor-image-enhancer-modal-prompt.webp"><img src="'+i+'" alt="Side-by-Side Image Enhancer Modal with Prompt Input"></a></p><h3 id="step-3-generate-the-enhancement" tabindex="-1"><a class="header-anchor" href="#step-3-generate-the-enhancement"><span>Step 3: Generate the Enhancement</span></a></h3><ol><li>Click the primary <strong>Generate</strong> button.</li><li>The AI processes the image and returns a high-resolution preview in the right-hand panel in 10 to 20 seconds.</li><li>Review the result. If you want adjustments, tweak your prompt and click <strong>↺ Regenerate</strong>.</li></ol><p><a class="doc-image-link" href="./assets/marketplace-vendor-image-enhancer-modal-result.webp"><img src="'+s+'" alt="Side-by-Side Dual Comparison Showing Original vs AI Enhanced Image Preview"></a></p><h3 id="step-4-apply-to-product" tabindex="-1"><a class="header-anchor" href="#step-4-apply-to-product"><span>Step 4: Apply to Product</span></a></h3><ol><li>When satisfied with the preview, click <strong>Insert</strong>.</li><li>Confirm the thumbnail replacement prompt.</li><li>The modal closes and automatically replaces the active image preview in your product form with the enhanced version, displaying the save reminder notice.</li><li>Click <strong>Update Product</strong> (or <strong>Save Product</strong>) on your dashboard to save the listing.</li></ol><p><a class="doc-image-link" href="./assets/marketplace-vendor-image-enhancer-applied.webp"><img src="'+l+'" alt="Enhanced Thumbnail Applied to Seller Product Form with Save Notice"></a></p><hr><h2 id="_3-key-differences-image-enhancer-vs-content-generator" tabindex="-1"><a class="header-anchor" href="#_3-key-differences-image-enhancer-vs-content-generator"><span>3. Key Differences: Image Enhancer vs. Content Generator</span></a></h2><table><thead><tr><th>Feature Dimension</th><th>Product Content Generator</th><th>Product Image Enhancer</th></tr></thead><tbody><tr><td><strong>Primary Goal</strong></td><td>Drafts text copy (Titles, Summaries, Descriptions, Prices, Attributes).</td><td>Upgrades visual product photography and main thumbnail presentation.</td></tr><tr><td><strong>Where to Launch</strong></td><td>Top of Add/Edit form or &quot;Create Product with AI&quot; on Products list.</td><td>Button positioned directly below the product thumbnail box.</td></tr><tr><td><strong>Input Format</strong></td><td>Text brief + optional reference photos.</td><td>Uploaded original photo + text styling prompt.</td></tr><tr><td><strong>Output Type</strong></td><td>Form field values (text &amp; numbers).</td><td>High-resolution optimized product photography.</td></tr><tr><td><strong>Application Mode</strong></td><td>Fills multiple form inputs across the page.</td><td>Swaps the featured product image attachment.</td></tr></tbody></table>',31)]))}]]),h=JSON.parse('{"path":"/documentation/magic-ai-image-enhancer.html","title":"Product Image Enhancer (Thumbnail AI Tool)","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"1. Accessing the Image Enhancer","slug":"_1-accessing-the-image-enhancer","link":"#_1-accessing-the-image-enhancer","children":[]},{"level":2,"title":"2. Step-by-Step Enhancement Workflow","slug":"_2-step-by-step-enhancement-workflow","link":"#_2-step-by-step-enhancement-workflow","children":[{"level":3,"title":"Step 1: Side-by-Side Visual Inspection","slug":"step-1-side-by-side-visual-inspection","link":"#step-1-side-by-side-visual-inspection","children":[]},{"level":3,"title":"Step 2: Formulate Your Enhancement Prompt","slug":"step-2-formulate-your-enhancement-prompt","link":"#step-2-formulate-your-enhancement-prompt","children":[]},{"level":3,"title":"Step 3: Generate the Enhancement","slug":"step-3-generate-the-enhancement","link":"#step-3-generate-the-enhancement","children":[]},{"level":3,"title":"Step 4: Apply to Product","slug":"step-4-apply-to-product","link":"#step-4-apply-to-product","children":[]}]},{"level":2,"title":"3. Key Differences: Image Enhancer vs. Content Generator","slug":"_3-key-differences-image-enhancer-vs-content-generator","link":"#_3-key-differences-image-enhancer-vs-content-generator","children":[]}],"git":{},"filePathRelative":"documentation/magic-ai-image-enhancer.md"}')}}]);